{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "ZL-2201, a pyrazolopyrimidine kinase inhibitor with a basic saturated heterocycle, has a predicted human absolute oral bioavailability of ~70%, directly supporting high F for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Alizapride, a methoxy-substituted heteroaromatic benzamide with a basic amine, showed absolute oral bioavailability of 72.5 ± 14.8% in subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tramadol, a methoxyphenyl cyclohexanol with a basic dimethylaminomethyl group, had mean absolute oral bioavailability of 67.9% after a 100 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Penbutolol, an aryloxypropanolamine with a basic amine, has an absolute oral bioavailability of 90% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Encainide, a methoxy-substituted basic drug, has a mean oral bioavailability of 42% with a range of 7–82%, supporting high typical F despite interindividual variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Rivastigmine, a polar carbamate with a basic amine, has an absolute oral bioavailability of ~36% at a 3 mg dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence from structurally related basic, polar drugs—including a pyrazolopyrimidine kinase inhibitor, alizapride, tramadol, penbutolol, encainide, and rivastigmine—shows absolute oral bioavailability values mostly 36–90%, all above the 20% threshold. The unfavorable physicochemical prior is outweighed by these direct measurements, so the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The most structurally similar analogue (ZL-2201) provides a predicted rather than measured human bioavailability value.",
    "Encainide shows wide interindividual bioavailability variability, including values below 20% in some patients.",
    "The record for C34 appears to describe ranolazine but the provided SMILES is inconsistent, adding uncertainty to that piece of evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

